export function getRegionalCropHistory(cropName: string, state?: string, district?: string) {
  const stLower = state ? state.toLowerCase().trim() : '';
  const crLower = cropName.toLowerCase().trim();
  const key = `${stLower}|${crLower}`;

  if (stLower && HISTORICAL_CROP_SUMMARY[key]) {
    const item = HISTORICAL_CROP_SUMMARY[key];
    return {
      crop: cropName,
      evidenceLevel: 'STATE_LEVEL',
      yearsObserved: item.yearsObserved,
      observationCount: item.observationCount,
      summaryNote: `Recorded across ${item.yearsObserved} agricultural seasons in ${item.state} (ICAR-DES Data).`,
    };
  }

  return {
    crop: cropName,
    evidenceLevel: 'GENERAL_CROP_KNOWLEDGE',
    yearsObserved: null,
    observationCount: null,
    summaryNote: 'Evaluated based on national agronomic compatibility benchmarks.',
  };
}
